   $ex${"titre":"Une journée à la ferme de Green Farm","competence":"manier-langue","situation":"Une ferme pédagogique distribue une affiche à l’entrée. Elle annonce les animaux et l’équipe.","documents":[{"id":"ferme","type":"texte","genre":"article","titre":"Green Farm","blocs":["Welcome to Green Farm! Come and meet 20 sheep and 3 deer in the fields.","Look for 8 mice in the barn. Children under five are free.","Our team: three men and two women. See you on Sunday!"],"source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux noms** dont le pluriel est **identique** au singulier.","aide":"Ce sont deux animaux : l’un a une laine, l’autre vit dans les bois.","type":"zone","document":"ferme","multiple":true},{"enonce":"Associe chaque singulier à son pluriel, comme sur l’affiche.","aide":"Ces quatre pluriels sont irréguliers : on ne met pas de -s.","type":"association","gauche":[{"id":"g0","texte":"mouse"},{"id":"g1","texte":"child"},{"id":"g2","texte":"man"},{"id":"g3","texte":"woman"}],"droite":[{"id":"d0","texte":"men"},{"id":"d1","texte":"women"},{"id":"d2","texte":"mice"},{"id":"d3","texte":"children"}]},{"enonce":"Range chaque nom selon la façon dont il fait son pluriel.","aide":"Regarde la fin du mot : -x, -ch, -o, consonne + y, -f ou -fe.","type":"categories","categories":[{"id":"c0","texte":"Pluriel en -es"},{"id":"c1","texte":"Pluriel en -ies ou -ves"},{"id":"c2","texte":"Pluriel irrégulier"}],"items":[{"id":"i0","texte":"knife"},{"id":"i1","texte":"potato"},{"id":"i2","texte":"box"},{"id":"i3","texte":"watch"},{"id":"i4","texte":"mouse"},{"id":"i5","texte":"tooth"},{"id":"i6","texte":"leaf"},{"id":"i7","texte":"city"},{"id":"i8","texte":"foot"}]},{"enonce":"Aya voit un deer dans le champ. Ben en voit trois. Complète.","aide":"Pense au mot de l’affiche qui ne change pas.","type":"trous","segments":["Aya sees one deer. Ben sees three ",0,"."]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m11"]},"explication":"**sheep** et **deer** ne changent pas au pluriel : one sheep, twenty sheep."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**mouse → mice, child → children, man → men, woman → women** : pluriels irréguliers à connaître par cœur."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c2","i5":"c2","i6":"c1","i7":"c1","i8":"c2"}},"explication":"**box, watch, potato** → -es ; **city → cities, leaf → leaves, knife → knives** ; **tooth, foot, mouse** changent de voyelle (teeth, feet, mice)."},{"cle":{"type":"trous","trous":[["deer"]]},"affichage":"deer","explication":"**deer** : ce nom est inchangé au pluriel (comme sheep et fish)."}]$ex$::jsonb),
  ('63a4aa8d-ba12-548f-b8be-114e11d012de'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les bonnes nouvelles de Kate","competence":"analyser-document","situation":"Kate écrit à son ami Sam : elle lui raconte ses bonnes nouvelles et lui parle du mobilier acheté pour sa chambre. Elle joint le ticket de caisse.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Un message de Kate","blocs":["Hi Sam,","I have good news! Our teacher gave me some advice about the exam, and Mum bought new furniture for my room. But I have a lot of homework today!"],"source":"Message écrit pour l’exercice"},{"id":"ticket","type":"fiche","modele":"ticket","entete":"Home & Co","sousTitre":"Saturday — 11:20","emoji":"🧾","lignes":[{"texte":"1 desk","valeur":"£60"},{"texte":"1 chair","valeur":"£25"},{"texte":"1 shelf","valeur":"£15"},{"separateur":true},{"texte":"TOTAL","valeur":"£100","gras":true}],"pied":"Thank you!","teinte":"bleu","source":"Ticket écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre noms indénombrables** du message.","aide":"Ces noms ne prennent jamais de -s et n’ont pas de « a / an ».","type":"zone","document":"mail","multiple":true},{"enonce":"D’après le ticket, **combien d’objets** de mobilier Mum a-t-elle achetés ?","aide":"Compte les lignes d’achat, sans la ligne TOTAL.","type":"nombre"},{"enonce":"Complète avec le partitif : on compte le mobilier par « pièces ».","aide":"Il y en a trois : le partitif prend la marque du pluriel.","type":"trous","segments":["Mum bought three ",0," of furniture."],"banque":["glasses","piece","pairs","pieces"]},{"enonce":"Kate annonce une bonne nouvelle. Complète avec le bon verbe.","aide":"News est indénombrable : le verbe est toujours au singulier.","type":"trous","segments":["The news ",0," good."],"banque":["have","were","is","are"]},{"enonce":"Quelle phrase est correcte ?","aide":"Advice est indénombrable : ni a, ni pluriel.","type":"choix","options":[{"id":"a","texte":"She gave me some good advice."},{"id":"b","texte":"She gave me a good advice."},{"id":"c","texte":"She gave me many advices."},{"id":"d","texte":"She gave me good advices."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m11","m19","m29"]},"explication":"**news, advice, furniture, homework** sont indénombrables, même si le français dit « des conseils » ou « des devoirs »."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"**3** objets : un bureau, une chaise, une étagère."},{"cle":{"type":"trous","trous":[["pieces"]]},"affichage":"pieces","explication":"**three pieces of furniture** : furniture reste au singulier, c’est le partitif qui se met au pluriel."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"**The news is good.** « News » se termine par -s, mais c’est un indénombrable : verbe au **singulier**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**She gave me some good advice.** Avec un indénombrable : pas de « a », pas de -s."}]$ex$::jsonb),
  ('c6047999-8bce-5f37-a362-4a8db56911cf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Si j’avais un chien","competence":"comprendre-langue","situation":"Lina et Max discutent de la météo de demain, puis Lina rêve à voix haute.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lina et Max","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"If it rains tomorrow, I will stay home."},{"qui":"Max","texte":"Me too. If it’s sunny, I will go to the park."},{"qui":"Lina","texte":"If I had a dog, I would take it to the park."},{"qui":"Max","texte":"You don’t have a dog!"},{"qui":"Lina","texte":"No, but if I had one, I would call him Bingo."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui montrent que Lina parle de quelque chose d’**irréel**.","aide":"Ils se trouvent dans la proposition principale, pas après *if*.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque phrase : condition **possible** (type 1) ou **irréelle** (type 2) ?","aide":"Lina a-t-elle vraiment un chien ?","type":"categories","categories":[{"id":"c0","texte":"Type 1 : possible"},{"id":"c1","texte":"Type 2 : irréel du présent"}],"items":[{"id":"i0","texte":"If it’s sunny, I will go to the park."},{"id":"i1","texte":"If I had a dog, I would take it to the park."},{"id":"i2","texte":"If I had one, I would call him Bingo."},{"id":"i3","texte":"If it rains tomorrow, I will stay home."}]},{"enonce":"Complète pour une condition irréelle.","aide":"On n’a pas de vélo : le verbe après *if* est au prétérit.","type":"trous","segments":["If I ",0," a bike, I would ride to school."],"banque":["will have","would have","had","have"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m43"]},"explication":"**would** (deux fois) : *if + prétérit, would + base verbale* exprime l’irréel du présent."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Type 1 : *if + présent, will*. Type 2 : *if + prétérit, would*, pour une situation irréelle."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** : *if + prétérit*, jamais *will* ni *would* après *if*."}]$ex$::jsonb),
  ('c6047999-8bce-5f37-a362-4a8db56911cf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à la directrice","competence":"argumenter","situation":"Zoe a mis un mot dans la boîte à idées du collège : elle explique ce qu’elle ferait si elle dirigeait l’établissement.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Mrs Bell","blocs":["Dear Mrs Bell, if I were the head teacher, I would build a swimming pool. If we had a pool, we would swim every Friday.","I would also change the canteen: if it served pizza, more students would eat there. Thank you for reading! Zoe, class 5B"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui est à la forme **were** après *if I*.","aide":"Il remplace *was* dans cette structure.","type":"zone","document":"lettre","multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"On emploie la même forme pour toutes les personnes.","type":"trous","segments":["If I ",0," you, I would apologise."],"banque":["be","am","will be","were"]},{"enonce":"Associe chaque condition de la lettre à sa conséquence.","aide":"Relis chaque phrase de Zoe.","type":"association","gauche":[{"id":"g0","texte":"If we had a pool,"},{"id":"g1","texte":"If the canteen served pizza,"},{"id":"g2","texte":"If I were the head teacher,"}],"droite":[{"id":"d0","texte":"I would build a swimming pool."},{"id":"d1","texte":"more students would eat there."},{"id":"d2","texte":"we would swim every Friday."}]},{"enonce":"Remets en ordre : « S’il pleuvait, nous jouerions à l’intérieur. » La phrase commence par If it.","aide":"Prétérit après *if*, would + base verbale dans la principale.","type":"ordre","items":[{"id":"a","texte":"rained,"},{"id":"b","texte":"If it"},{"id":"c","texte":"we would"},{"id":"d","texte":"inside"},{"id":"e","texte":"play"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**were** : dans la condition de type 2, on emploie **were** à toutes les personnes (*if I were…*)."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : *If I were you, I would…* est la forme à retenir."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**if + prétérit, would + base verbale** : chaque condition irréelle est suivie de sa conséquence."},{"cle":{"type":"ordre","ids":["b","a","c","e","d"]},"explication":"**If it rained, we would play inside** : type 2, avec une virgule après la proposition en *if*."}]$ex$::jsonb),
  ('c6047999-8bce-5f37-a362-4a8db56911cf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le bus manqué d’Ellie","competence":"argumenter","situation":"Ellie a raté la sortie scolaire. Le journal du collège raconte l’histoire, puis ses camarades réagissent.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"School news","blocs":["Ellie missed the museum trip last Saturday. She says: “If I had gone to bed earlier, I would have caught the bus.”","Next time, if she sets two alarms, she will arrive on time."],"source":"Article écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de la classe","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Ruby","emoji":"👧","cote":"droite"},{"nom":"Ellie","emoji":"👩","cote":"gauche"}],"repliques":[{"qui":"Sam","texte":"If you had told me, I would have woken you up."},{"qui":"Ruby","texte":"If you come with us next time, you will love the museum."},{"qui":"Ellie","texte":"If I had a car, I would drive to the museum myself!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Dans la proposition en *if* d’Ellie, touche les **deux mots** qui forment le past perfect.","aide":"Cherche *had* et le participe passé qui le suit.","type":"zone","document":"journal","multiple":true},{"enonce":"Que signifie « If I had gone to bed earlier, I would have caught the bus » ?","aide":"Une condition de type 3 parle du contraire de ce qui s’est passé.","type":"choix","options":[{"id":"a","texte":"Ellie ne s’est pas couchée tôt et elle a manqué le bus."},{"id":"b","texte":"Ellie ne se couche jamais tôt et prend toujours le bus."},{"id":"c","texte":"Ellie ne se couchera pas tôt demain."},{"id":"d","texte":"Ellie s’est couchée tôt et elle a pris le bus."}],"multiple":false},{"enonce":"Range chaque phrase selon son **type** de condition.","aide":"Regarde le temps du verbe après *if*.","type":"categories","categories":[{"id":"c0","texte":"Type 1 (possible)"},{"id":"c1","texte":"Type 2 (irréel du présent)"},{"id":"c2","texte":"Type 3 (irréel du passé)"}],"items":[{"id":"i0","texte":"If I had gone to bed earlier, I would have caught the bus."},{"id":"i1","texte":"If you come with us next time, you will love the museum."},{"id":"i2","texte":"If you had told me, I would have woken you up."},{"id":"i3","texte":"If I had a car, I would drive to the museum myself!"}]},{"enonce":"Complète pour une condition possible.","aide":"Condition de type 1 : présent après *if*.","type":"trous","segments":["Next time, if Ellie ",0," two alarms, she will arrive on time."],"banque":["would set","will set","sets","set"]},{"enonce":"Remets en ordre : « Si j’avais su, je te l’aurais dit. » La phrase commence par If I.","aide":"Past perfect après *if*, would have + participe dans la principale.","type":"ordre","items":[{"id":"a","texte":"have told"},{"id":"b","texte":"you"},{"id":"c","texte":"had known,"},{"id":"d","texte":"I would"},{"id":"e","texte":"If I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m12"]},"explication":"**had** et **gone** : *if + past perfect* exprime un regret sur le passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"Type 3 : **if + past perfect, would have + participe passé**. Les faits réels sont l’inverse."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c2","i3":"c1"}},"explication":"Présent → type 1 ; prétérit → type 2 ; past perfect → type 3."},{"cle":{"type":"trous","trous":[["sets"]]},"affichage":"sets","explication":"**sets** : après *if*, on emploie le **présent** pour une condition possible."},{"cle":{"type":"ordre","ids":["e","c","d","a","b"]},"explication":"**If I had known, I would have told you** : troisième condition."}]$ex$::jsonb),
  ('eaf70f0e-b304-52ac-8501-33f4e40a6537'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Des messages à rapporter","competence":"comprendre-langue","situation":"Ava et Ben échangent des messages. Plus tard, Ava les raconte à sa mère au discours indirect.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Ava et de Ben","participants":[{"nom":"Ava","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ava","texte":"I am tired."},{"qui":"Ben","texte":"I can’t come tonight, sorry."},{"qui":"Ava","texte":"OK. I will call you tomorrow."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot du premier message qui devient *was* au discours indirect.","aide":"Le présent recule d’un cran au prétérit.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète.","aide":"Le verbe introducteur est au passé.","type":"trous","segments":["Ava said she ",0," tired."],"banque":["is","was","had been","were"]},{"enonce":"Ava dit « I will call you tomorrow ». Quelle est la phrase rapportée ?","aide":"*Will* devient *would*, et *tomorrow* change aussi.","type":"choix","options":[{"id":"a","texte":"Ava said she would call him the next day."},{"id":"b","texte":"Ava said she will call him tomorrow."},{"id":"c","texte":"Ava said she would call him tomorrow."},{"id":"d","texte":"Ava said she called him the next day."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**am** : le présent simple devient un prétérit (*was*) après *said*."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**Ava said she was tired.** : recul des temps, présent → prétérit."},{"cle":{"type":"choix","ids":["a"]},"explication":"**would** et **the next day** : *will* → *would* ; *tomorrow* → *the next day*."}]$ex$::jsonb),
  ('eaf70f0e-b304-52ac-8501-33f4e40a6537'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Ce que Tom a dit","competence":"lire-tableau","situation":"Tom raconte sa journée. Sa sœur rapporte ses paroles à leur mère. Complète les lignes du tableau.","documents":[{"id":"tab","type":"tableau","titre":"Tom’s words","colonnes":["Paroles de Tom","Discours indirect"],"lignes":[["« I play football. »","Tom said he played football."],["« I am late. »","?"],["« I can swim. »","?"],["« I saw her. »","?"],["« Where do you live? »","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la phrase qui devient un **past perfect** au discours indirect.","aide":"Un prétérit recule d’un cran.","type":"zone","document":"tab","multiple":false},{"enonce":"Complète la 2e ligne du tableau.","aide":"Le présent de *be* recule au prétérit.","type":"trous","segments":["Tom said he ",0," late."],"banque":["be","was","is","were"]},{"enonce":"Complète la 3e ligne du tableau : « Tom said he ___ swim. »","aide":"*Can* recule d’un cran.","type":"choix","options":[{"id":"a","texte":"must"},{"id":"b","texte":"would"},{"id":"c","texte":"can"},{"id":"d","texte":"could"}],"multiple":false},{"enonce":"Remets en ordre la 4e ligne du tableau. La phrase commence par *Tom*.","aide":"Prétérit direct → past perfect indirect.","type":"ordre","items":[{"id":"a","texte":"Tom"},{"id":"b","texte":"had"},{"id":"c","texte":"he"},{"id":"d","texte":"said"},{"id":"e","texte":"her"},{"id":"f","texte":"seen"}]},{"enonce":"Remets en ordre la dernière ligne (question rapportée). La phrase commence par *Tom*.","aide":"Une question rapportée reprend l’ordre de l’affirmative.","type":"ordre","items":[{"id":"a","texte":"lived"},{"id":"b","texte":"asked"},{"id":"c","texte":"I"},{"id":"d","texte":"me"},{"id":"e","texte":"Tom"},{"id":"f","texte":"where"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**« I saw her. »** : le prétérit devient un past perfect (*he had seen her*)."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**Tom said he was late.** : *am* → *was*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**could** : *can* → *could* au discours indirect."},{"cle":{"type":"ordre","ids":["a","d","c","b","f","e"]},"explication":"**Tom said he had seen her.** : *saw* → *had seen*."},{"cle":{"type":"ordre","ids":["e","b","d","f","c","a"]},"explication":"**Tom asked me where I lived.** : ordre sujet + verbe, et recul au prétérit."}]$ex$::jsonb),
  ('eaf70f0e-b304-52ac-8501-33f4e40a6537'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les messages de maman","competence":"analyser-document","situation":"Zoé échange avec sa mère avant une soirée. Le lendemain, elle raconte la conversation à son amie.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de maman et de Zoé","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Zoe","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Don’t be late tonight."},{"qui":"Zoe","texte":"I will be home at six."},{"qui":"Mum","texte":"Did you finish your homework?"},{"qui":"Zoe","texte":"I haven’t finished it yet. I will do it tomorrow."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Comment rapporte-t-on l’ordre « Don’t be late tonight » ?","aide":"Un ordre rapporté : *tell* + personne + *to* + base verbale.","type":"choix","options":[{"id":"a","texte":"Mum told Zoe that she doesn’t be late that night."},{"id":"b","texte":"Mum said Zoe not be late that night."},{"id":"c","texte":"Mum told Zoe not to be late that night."},{"id":"d","texte":"Mum told Zoe didn’t be late that night."}],"multiple":false},{"enonce":"Mum a posé une question fermée. Complète.","aide":"Une question qui appelle « oui » ou « non » se rapporte avec un mot de doute.","type":"trous","segments":["Mum asked Zoe ",0," she had finished her homework."],"banque":["what","whether","if","that"]},{"enonce":"Touche les **deux repères de temps** qui changent au discours indirect.","aide":"*Tonight* et *tomorrow* ne se disent plus tels quels.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque élément du discours direct à sa forme rapportée.","aide":"Applique le recul des temps et les changements de repères.","type":"association","gauche":[{"id":"g0","texte":"tonight"},{"id":"g1","texte":"tomorrow"},{"id":"g2","texte":"I will be home"},{"id":"g3","texte":"I haven’t finished"}],"droite":[{"id":"d0","texte":"the next day"},{"id":"d1","texte":"that night"},{"id":"d2","texte":"she hadn’t finished"},{"id":"d3","texte":"she would be home"}]},{"enonce":"Remets en ordre : « Maman a demandé si elle était prête. » La phrase commence par *Mum*.","aide":"Après *if*, on garde l’ordre sujet + verbe.","type":"ordre","items":[{"id":"a","texte":"Mum"},{"id":"b","texte":"she"},{"id":"c","texte":"was"},{"id":"d","texte":"ready"},{"id":"e","texte":"asked"},{"id":"f","texte":"if"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"**told Zoe not to be late** : ordre négatif = *tell* + complément + *not to* + base verbale."},{"cle":{"type":"trous","trous":[["if","whether"]]},"affichage":"if","explication":"**if** ou **whether** : introduit une question fermée rapportée, sans inversion."},{"cle":{"type":"zone","ids":["m3","m24"]},"explication":"**tonight** → *that night* ; **tomorrow** → *the next day*."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"*tonight* → **that night** ; *tomorrow* → **the next day** ; *will* → **would** ; *haven’t finished* → **hadn’t finished**."},{"cle":{"type":"ordre","ids":["a","e","f","b","c","d"]},"explication":"**Mum asked if she was ready.** : question rapportée avec *if*, ordre de l’affirmative."}]$ex$::jsonb),
  ('838f6ae6-a475-5555-abfc-9190d3a3f2f4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Au club de natation","competence":"comprendre-langue","situation":"Kim s’inscrit au club de natation. Dan, le moniteur, lui pose quelques questions.","documents":[{"id":"natation","type":"dialogue","modele":"sms","titre":"Messages de Dan et Kim","participants":[{"nom":"Dan","emoji":"🏊","cote":"gauche"},{"nom":"Kim","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Dan","texte":"Can you swim?"},{"qui":"Kim","texte":"Yes, I can. I can swim and I can dive. But I can’t ride a horse."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la forme **négative** de can.","aide":"Elle se termine par -n’t.","type":"zone","document":"natation","multiple":false},{"enonce":"Comment demande-t-on « Sais-tu nager ? »","aide":"Can est un modal : il passe devant le sujet, sans do ni to.","type":"choix","options":[{"id":"a","texte":"Are you can swim?"},{"id":"b","texte":"Can you to swim?"},{"id":"c","texte":"Can you swim?"},{"id":"d","texte":"Do you can swim?"}],"multiple":false},{"enonce":"Remets en ordre : « Je sais faire du vélo. » La phrase commence par I.","aide":"Sujet, modal, verbe à la base.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"ride"},{"id":"c","texte":"can"},{"id":"d","texte":"I"},{"id":"e","texte":"bike"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**can’t** (ou *cannot*) est la négation de can."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Can you swim?** Le modal se place devant le sujet ; le verbe est à la base, sans to."},{"cle":{"type":"ordre","ids":["d","c","b","a","e"]},"explication":"**I can ride a bike.** Can est invariable, suivi du verbe sans to."}]$ex$::jsonb),
  ('838f6ae6-a475-5555-abfc-9190d3a3f2f4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’histoire de Gran","competence":"manier-langue","situation":"Une élève raconte ce que sa grand-mère était capable de faire, hier comme demain.","documents":[{"id":"gran","type":"texte","genre":"recit","titre":"Gran’s story","blocs":["My gran is 70 now, but she is very strong.","When she was a girl, she could run very fast.","Last winter, a storm closed the road. Gran was able to reach the village on foot.","Next summer, she will be able to swim in the lake again."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui exprime la **capacité passée générale**.","aide":"Elle courait vite quand elle était petite.","type":"zone","document":"gran","multiple":false},{"enonce":"Associe chaque situation à la forme qui l’exprime.","aide":"Une réussite ponctuelle n’emploie pas could.","type":"association","gauche":[{"id":"g0","texte":"capacité présente"},{"id":"g1","texte":"capacité passée générale"},{"id":"g2","texte":"réussite précise au passé"},{"id":"g3","texte":"capacité future"}],"droite":[{"id":"d0","texte":"could"},{"id":"d1","texte":"can"},{"id":"d2","texte":"was able to"},{"id":"d3","texte":"will be able to"}]},{"enonce":"Touche le mot qui montre que Gran a **réussi cette fois-là** à atteindre le village.","aide":"La tempête n’a eu lieu qu’une fois.","type":"zone","document":"gran","multiple":false},{"enonce":"Gran pourra nager l’été prochain. Complète.","aide":"Can n’a pas de futur.","type":"trous","segments":["Next summer, Gran ",0," swim in the lake."],"banque":["must","can","will be able to","could"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**could** : capacité passée générale (« elle savait courir »)."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**can**, **could**, **was/were able to**, **will be able to** : une forme pour chaque situation."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**was able to** : réussite ponctuelle au passé, on n’emploie pas could."},{"cle":{"type":"trous","trous":[["will be able to"]]},"affichage":"will be able to","explication":"**will be able to** : forme de remplacement pour exprimer la capacité au futur."}]$ex$::jsonb),
  ('838f6ae6-a475-5555-abfc-9190d3a3f2f4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un camp de natation au bord du lac","competence":"analyser-document","situation":"Tom est en camp de natation au bord d’un lac. Il écrit à son père, et son moniteur note ses progrès.","documents":[{"id":"lac","type":"dialogue","modele":"sms","titre":"Messages de Tom à Dad","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Hi Dad! From my window I can see the sea and I can hear the waves."},{"qui":"Tom","texte":"Yesterday the lake was very cold, but I was able to swim 100 metres!"},{"qui":"Tom","texte":"Could you send me my goggles, please?"}],"source":"Messages écrits pour l’exercice"},{"id":"tests","type":"tableau","titre":"Tom’s swimming test","colonnes":["Week","Distance"],"lignes":[["Week 1","25 m"],["Week 2","50 m"],["Week 3","100 m"]],"source":"Résultats inventés pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes de perception** que Tom emploie avec *can*.","aide":"Ce sont des verbes qui parlent de ce qu’on voit et de ce qu’on entend.","type":"zone","document":"lac","multiple":true},{"enonce":"Pourquoi Tom écrit-il « **Could** you send me… » et non « Can you… » ?","aide":"Pense à la manière de demander gentiment un service.","type":"choix","options":[{"id":"a","texte":"Can n’existe pas dans les questions"},{"id":"b","texte":"Could exprime une réussite précise"},{"id":"c","texte":"Could rend la demande plus polie"},{"id":"d","texte":"Could parle d’une action déjà terminée"}],"multiple":false},{"enonce":"D’après le tableau, **de combien de mètres** Tom a-t-il progressé entre la semaine 1 et la semaine 3 ?","aide":"Soustrais la première distance à la dernière.","type":"nombre","unite":"m"},{"enonce":"En semaine 3, Tom a réussi son test (une réussite précise). Complète.","aide":"C’est une réussite ponctuelle, au passé.","type":"trous","segments":["In week 3, Tom ",0," swim 100 m."],"banque":["can","was able to","must","will be able to"]},{"enonce":"Remets en ordre : « Tu pourras peut-être venir. » La phrase commence par You.","aide":"Après might, on emploie be able to.","type":"ordre","items":[{"id":"a","texte":"might"},{"id":"b","texte":"come"},{"id":"c","texte":"be"},{"id":"d","texte":"You"},{"id":"e","texte":"able"},{"id":"f","texte":"to"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**see** et **hear** : avec les verbes de perception, l’anglais emploie *can*, là où le français dit simplement « je vois, j’entends »."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Could you…?** est une formule plus polie que *Can you…?*."},{"cle":{"type":"nombre","valeur":75,"tolerance":0},"affichage":"75 m","explication":"100 − 25 = **75** mètres de progrès."},{"cle":{"type":"trous","trous":[["was able to"]]},"affichage":"was able to","explication":"**was able to** : réussite ponctuelle au passé."},{"cle":{"type":"ordre","ids":["d","a","c","e","f","b"]},"explication":"**You might be able to come.** Après un modal, on emploie la forme de remplacement *be able to*."}]$ex$::jsonb),
  ('f67d09fc-f9e9-54a8-91d0-f117c075d1cf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un téléphone tout neuf","competence":"comprendre-langue","situation":"Léa raconte à une amie l’achat de son téléphone. L’ordre des mots anglais est strict : sujet, verbe, complément.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"Léa’s weekend","blocs":["Last Saturday I bought a new phone in town. It was raining, so I took a taxi.","There is a problem now: my sister borrowed it."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le **nom** qui est le complément d’objet de *bought*.","aide":"Qu’est-ce que Léa a acheté ?","type":"zone","document":"texte","multiple":false},{"enonce":"Remets en ordre : « Elle a joué du piano magnifiquement au concert hier soir. » La phrase commence par She.","aide":"Après l’objet : manière, lieu, temps.","type":"ordre","items":[{"id":"a","texte":"last night"},{"id":"b","texte":"beautifully"},{"id":"c","texte":"She"},{"id":"d","texte":"played"},{"id":"e","texte":"the piano"},{"id":"f","texte":"at the concert"}]},{"enonce":"Pourquoi écrit-on « It was raining » et non « Was raining » ?","aide":"Regarde la phrase sans *it* : que manque-t-il ?","type":"choix","options":[{"id":"a","texte":"Parce que le sujet est obligatoire en anglais."},{"id":"b","texte":"Parce que le prétérit exige *it*."},{"id":"c","texte":"Parce que *rain* est un verbe irrégulier."},{"id":"d","texte":"Parce que *raining* est un nom."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**phone** : *I (S) bought (V) a new phone (O)* suit l’ordre sujet – verbe – objet."},{"cle":{"type":"ordre","ids":["c","d","e","b","f","a"]},"explication":"**She played the piano beautifully at the concert last night** : sujet, verbe, objet, puis manière → lieu → temps."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **sujet est obligatoire** en anglais, même quand il est vide : *It was raining*."}]$ex$::jsonb),
  ('f67d09fc-f9e9-54a8-91d0-f117c075d1cf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La soirée de Lou","competence":"manier-langue","situation":"Lou raconte sa soirée dans un petit article. Il y a des phrases coordonnées et des phrases subordonnées.","documents":[{"id":"soiree","type":"texte","genre":"article","titre":"Lou’s evening","blocs":["I was tired, so I went to bed early. I wanted to read, but my eyes hurt.","My sister, who sleeps in the next room, was playing music that I don’t like. I will tell her when she comes home."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots de coordination** qui relient deux propositions de même rang.","aide":"Ce sont des petits mots entre deux propositions.","type":"zone","document":"soiree","multiple":true},{"enonce":"Range chaque mot du texte : **coordination** ou **subordination** ?","aide":"La subordination fait dépendre une proposition d’une autre.","type":"categories","categories":[{"id":"c0","texte":"Coordination"},{"id":"c1","texte":"Subordination"}],"items":[{"id":"i0","texte":"but"},{"id":"i1","texte":"when"},{"id":"i2","texte":"so"},{"id":"i3","texte":"who"}]},{"enonce":"Complète après la conjonction de temps.","aide":"Après *as soon as*, on emploie le présent.","type":"trous","segments":["I’ll call you as soon as I ",0," home."],"banque":["get","getting","will get","got"]},{"enonce":"Remets en ordre : « Je n’ai vu personne. » La phrase commence par I.","aide":"Une seule négation par phrase.","type":"ordre","items":[{"id":"a","texte":"see"},{"id":"b","texte":"anybody"},{"id":"c","texte":"didn’t"},{"id":"d","texte":"I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m13"]},"explication":"**so** et **but** coordonnent deux propositions : elles ont le **même rang**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"**so, but** relient deux propositions de même rang ; **who** (relative) et **when** (temps) introduisent une subordonnée."},{"cle":{"type":"trous","trous":[["get"]]},"affichage":"get","explication":"**get** : après une conjonction de temps, on emploie le **présent** pour l’avenir."},{"cle":{"type":"ordre","ids":["d","c","a","b"]},"explication":"**I didn’t see anybody** : l’anglais n’admet pas de double négation (*nobody*)."}]$ex$::jsonb),
  ('f67d09fc-f9e9-54a8-91d0-f117c075d1cf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le club d’échecs","competence":"argumenter","situation":"Noor et Ali découvrent le club d’échecs du collège. Ils lisent le règlement, puis échangent des messages.","documents":[{"id":"club","type":"texte","genre":"article","titre":"Chess club","blocs":["Our chess club meets on Fridays at four o’clock. You can bring a friend if you ask Mr Hall first.","Unless it rains, we play in the yard. We use the library when it is cold. In order to win more games, practise every week."],"source":"Règlement écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Noor et Ali","participants":[{"nom":"Noor","emoji":"👧","cote":"gauche"},{"nom":"Ali","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Noor","texte":"I speak English well, but I didn’t understand the rules."},{"qui":"Ali","texte":"I think they are simple. I often play with my brother."},{"qui":"Noor","texte":"I will call you when I arrive on Friday."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction qui veut dire « **à moins que** ».","aide":"C’est le premier mot d’une phrase du règlement.","type":"zone","document":"club","multiple":false},{"enonce":"Range chaque morceau du règlement selon le **type** de subordonnée.","aide":"Pense à la question : quand ? sous quelle condition ? pour quoi ?","type":"categories","categories":[{"id":"c0","texte":"Temps"},{"id":"c1","texte":"Condition"},{"id":"c2","texte":"But"}],"items":[{"id":"i0","texte":"in order to win more games"},{"id":"i1","texte":"unless it rains"},{"id":"i2","texte":"if you ask Mr Hall first"},{"id":"i3","texte":"when it is cold"}]},{"enonce":"Complète le mot omis.","aide":"C’est un mot qu’on peut souvent omettre après *I think*.","type":"trous","segments":["I think ",0," they are simple."],"banque":["where","which","that","who"]},{"enonce":"Touche l’**adverbe de fréquence** dans les messages.","aide":"Il répond à « à quelle fréquence ? ».","type":"zone","document":"sms","multiple":false},{"enonce":"Quelle phrase est correcte ?","aide":"Une seule négation, et la base verbale après *didn’t*.","type":"choix","options":[{"id":"a","texte":"We didn’t met anyone at the club."},{"id":"b","texte":"We didn’t meet no one at the club."},{"id":"c","texte":"We met not anyone at the club."},{"id":"d","texte":"We didn’t meet anyone at the club."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"**Unless** exprime une condition négative (« à moins que »)."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**when** : temps ; **if, unless** : condition ; **in order to** : but."},{"cle":{"type":"trous","trous":[["that"]]},"affichage":"that","explication":"**that** introduit la subordonnée complétive ; il est souvent omis dans « I think they are simple »."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**often** se place **avant** le verbe lexical : *I often play*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**We didn’t meet anyone** : pas de double négation, base verbale après *didn’t*."}]$ex$::jsonb),
  ('9d2bd35f-6f7f-5753-a1fb-86e7b856c46a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le téléphone perdu","competence":"comprendre-langue","situation":"Jo a perdu son téléphone au collège. Sam l’aide à le retrouver.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Jo et Sam","participants":[{"nom":"Jo","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jo","texte":"I can’t find my phone. Can you help me?"},{"qui":"Sam","texte":"Sure! Is this blue phone yours?"},{"qui":"Jo","texte":"No, mine is red. That one is Lily’s. She lost it yesterday."},{"qui":"Sam","texte":"I’ll give it to her at school."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le **pronom complément** qui remplace *Lily*.","aide":"Un pronom complément suit le verbe ou une préposition.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète avec le pronom possessif.","aide":"Il remplace « mon téléphone » sans nom derrière.","type":"trous","segments":["No, ",0," is red."],"banque":["myself","my","me","mine"]},{"enonce":"Que remplace *it* dans « She lost it yesterday » ?","aide":"Relis la phrase d’avant : *That one is Lily’s*.","type":"choix","options":[{"id":"a","texte":"Lily elle-même."},{"id":"b","texte":"Le collège."},{"id":"c","texte":"Le téléphone de Lily."},{"id":"d","texte":"Le téléphone de Jo."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"**her** : après la préposition *to*, le pronom complément de *she* est **her**."},{"cle":{"type":"trous","trous":[["mine"]]},"affichage":"mine","explication":"**mine** : le pronom possessif de *I* s’emploie sans nom (*mine is red*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**it** reprend une chose : ici le téléphone de Lily."}]$ex$::jsonb),
  ('9d2bd35f-6f7f-5753-a1fb-86e7b856c46a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Merci pour la fête","competence":"manier-langue","situation":"Après l’anniversaire d’Emma, une amie lui écrit une carte de remerciement. Emma lui répond par message.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Dear Emma","blocs":["Dear Emma, we had a great time at your party. Tom himself made a joke, and my brother made the cake himself!","We want to thank you and your parents. Our gift is for you: this card is from us."],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Message d’Emma","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Lou","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Thanks! I get up at six on Saturdays. I wash and I dress quickly. I don’t feel tired."}],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux pronoms réfléchis** de la lettre.","aide":"Ils se terminent par -self.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque pronom sujet à son pronom complément.","aide":"Le pronom complément suit le verbe ou une préposition.","type":"association","gauche":[{"id":"g0","texte":"I"},{"id":"g1","texte":"she"},{"id":"g2","texte":"we"},{"id":"g3","texte":"they"}],"droite":[{"id":"d0","texte":"me"},{"id":"d1","texte":"her"},{"id":"d2","texte":"them"},{"id":"d3","texte":"us"}]},{"enonce":"Complète avec le pronom réfléchi.","aide":"Il insiste sur celui qui l’a fait : un garçon.","type":"trous","segments":["My brother made the cake ",0,"."],"banque":["herself","itself","him","himself"]},{"enonce":"Pourquoi n’y a-t-il pas de *myself* dans « I wash and I dress quickly » ?","aide":"En français, on dit « je me lave » : et en anglais ?","type":"choix","options":[{"id":"a","texte":"Parce que *myself* est réservé à l’écrit formel."},{"id":"b","texte":"Parce que le sujet est au pluriel dans ce message."},{"id":"c","texte":"Parce qu’Emma est seule quand elle se prépare."},{"id":"d","texte":"Ces verbes ne prennent pas de réfléchi en anglais."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"**himself** (deux fois) : ici, le pronom réfléchi sert à **insister** (*il l’a fait lui-même*)."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"I – **me**, she – **her**, we – **us**, they – **them**."},{"cle":{"type":"trous","trous":[["himself"]]},"affichage":"himself","explication":"**himself** : le pronom réfléchi de *he* ; il dit « il l’a fait lui-même »."},{"cle":{"type":"choix","ids":["d"]},"explication":"Certains verbes pronominaux français ne le sont pas en anglais : **I wash**, **I get up**, **I feel**, sans pronom réfléchi."}]$ex$::jsonb),
  ('9d2bd35f-6f7f-5753-a1fb-86e7b856c46a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"À qui est-ce ?","competence":"argumenter","situation":"Le collège range les objets trouvés. La surveillante interroge les élèves pour rendre chaque objet à son propriétaire.","documents":[{"id":"objets","type":"tableau","titre":"Les objets trouvés","colonnes":["Object","Owner"],"lignes":[["Blue bag","Ava"],["Green scarf","Noah"],["Yellow ball","the twins"]],"enteteLignes":false,"source":"Liste écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Mme Lee, Ava et Noah","participants":[{"nom":"Ms Lee","emoji":"👩","cote":"gauche"},{"nom":"Ava","emoji":"👧","cote":"droite"},{"nom":"Noah","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ms Lee","texte":"It’s late, Ava. Is the blue bag yours?"},{"qui":"Ava","texte":"Yes, it’s mine! I looked for it by myself."},{"qui":"Ms Lee","texte":"Good. Noah, the green scarf is yours, I think."},{"qui":"Noah","texte":"Thanks, miss. And the ball? I think it belongs to the twins."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Le foulard est à Noah. Complète avec le pronom possessif.","aide":"Noah est un garçon.","type":"trous","segments":["The scarf is Noah’s. It’s ",0,"."],"banque":["he","his","himself","him"]},{"enonce":"La balle est aux jumeaux. Complète avec le pronom possessif.","aide":"Il remplace « leur balle », sans nom derrière.","type":"trous","segments":["The ball is the twins’. It’s ",0,"."],"banque":["them","their","themselves","theirs"]},{"enonce":"Touche les **deux mots** qui disent qu’Ava a cherché son sac **toute seule**.","aide":"Cherche la préposition et le pronom réfléchi.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque pronom : **complément**, **possessif** ou **réfléchi** ?","aide":"Les réfléchis finissent par -self ou -selves ; les possessifs s’emploient sans nom.","type":"categories","categories":[{"id":"c0","texte":"Pronom complément"},{"id":"c1","texte":"Pronom possessif"},{"id":"c2","texte":"Pronom réfléchi"}],"items":[{"id":"i0","texte":"themselves"},{"id":"i1","texte":"them"},{"id":"i2","texte":"ours"},{"id":"i3","texte":"us"},{"id":"i4","texte":"yourself"},{"id":"i5","texte":"hers"}]},{"enonce":"Que représente *it* dans « It’s late, Ava » ?","aide":"Peut-on remplacer *it* par un objet précis ?","type":"choix","options":[{"id":"a","texte":"Le foulard vert que Noah a perdu."},{"id":"b","texte":"Le sac bleu que Mme Lee a trouvé."},{"id":"c","texte":"La surveillante qui range les objets."},{"id":"d","texte":"Un sujet vide : il parle de l’heure."}],"multiple":false}]}$ex$::jsonb,
